INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Queen''s Quest 3: The End of Dawn', 'In Queen''s Quest 3: The End of Dawn you will follow Eliana as she tries to become a true alchemist. You will need to help her solve riddles, explore kingdoms and much more. Follow Eliana on her mission to save her hometown and help her to save the people she loves. Tackle the evil forces behind a deadly betrayal and prove yourself to be a true alchemist.' FROM games WHERE igdb_id = 28310 ON CONFLICT (game_id, language_code) DO NOTHING;
