INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Epic Tavern', 'Run your Tavern and take hold of your destiny in the World of Beor. Epic Tavern is a PC video game, where YOU take on the righteous role and responsibility of a Tavernmaster. You will build a legendary Tavern to attract Heroes from every corner of Beor. By bringing together courageous parties and sending them off on dangerous [and oftentimes crazy] adventures, every decision you make will alter theirs and your own destiny in Epic Tavern!' FROM games WHERE igdb_id = 25644 ON CONFLICT (game_id, language_code) DO NOTHING;
