INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghost Blade HD', 'Ghost Blade HD is an intense bullet-hell shoot ''em up game, with satisfying and addictive score-based gameplay, with its inspiration going back to the shooting games of the 1990s era, Ghost Blade HD ties old memories to current tones and techniques. Designed with a modern graphic style and special effects, Ghost Blade HD also features an awesome 2-player and TATE mode! Ghost Blade HD is easy to learn, hard to master.' FROM games WHERE igdb_id = 26947 ON CONFLICT (game_id, language_code) DO NOTHING;
