INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MudRunner', 'Like Spintires before it, Spintires: MudRunner puts players in the driver seat and dares them to take charge of incredible all-terrain vehicles, venturing across extreme Siberian landscapes with only a map and compass as guides! This edition comes complete with a brand new Sandbox Map joining the original game''s 5 environments, a total graphical overhaul, a new Challenge mode with 9 new dedicated maps, 13 new vehicles and other comprehensive improvements.' FROM games WHERE igdb_id = 54789 ON CONFLICT (game_id, language_code) DO NOTHING;
