INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Free Fire', 'Free Fire is the ultimate survival shooter game available on mobile. Each 10-minute game places you on a remote island where you are pit against 49 other players, all seeking survival. Players freely choose their starting point with their parachute, and aim to stay in the safe zone for as long as possible. Drive vehicles to explore the vast map, hide in the wild, or become invisible by proning under grass or rifts. Ambush, snipe, survive, there is only one goal: to survive and answer the call of duty.' FROM games WHERE igdb_id = 87622 ON CONFLICT (game_id, language_code) DO NOTHING;
