INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Franchise Hockey Manager 4', 'The Most Hockey Ever! Franchise Hockey Manager 4 is the deepest, most authentic hockey strategy game available. FHM 4 is officially licensed by the NHL®, includes real 2017-18 rosters, packs even more features than any of its predecessors, and takes the series to a whole new level in terms of realism and gameplay.' FROM games WHERE igdb_id = 69422 ON CONFLICT (game_id, language_code) DO NOTHING;
