INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Evolution Soccer 2018', 'Pro Evolution Soccer 2018 is a football simulation game developed and published by Konami in 2017. It features updated teams, players, and competitions with a focus on realistic gameplay and presentation. The game introduces improved ball control, dribbling mechanics, and enhanced player animations. Modes include Master League, Become a Legend, online multiplayer, and licensed tournaments such as the UEFA Champions League.' FROM games WHERE igdb_id = 28862 ON CONFLICT (game_id, language_code) DO NOTHING;
