INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Just Dance 2018', 'No matter where you come from, how old you are, if you are a panda or a carrot: turn up the volume and get ready to unleash your inner dancer, because Just Dance 2018 brings out the dancer in everyone! The biggest music video game franchise of all time, with over 63 million units sold is coming back this fall. Whether you are a party starter, a young dancer in the making or a pro dancer looking for new challenges, it’s never been so easy to Just Dance!' FROM games WHERE igdb_id = 37067 ON CONFLICT (game_id, language_code) DO NOTHING;
