INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atomine', 'Atomine is a twin stick procedural shooter rogue-lite set in a virtual world with minimalist design, where the player recounts on the screen the real events of Stuxnet, the first weapon ever created in the form of computer virus. In every run the player has to clear the level area from all the enemies in order to unlock the portal to the next level. During the run every killed enemy will leave on the ground XPs, energy and/or weapon modules.' FROM games WHERE igdb_id = 28554 ON CONFLICT (game_id, language_code) DO NOTHING;
