INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cruis''n Blast', 'Cruis''n Blast, developed by the crack Raw Thrills studio team, takes Cruis''n into the new millennium as players zoom 200 mph through the bustle of London, blast through the exotic wonders of Madagascar, celebrate Carnival in Rio, amaze to the hi tech splendor of Singapore, and drive an earth-shaking thriller through Death Valley. Raw Thrills and Nintendo have worked together to deliver a new arcade game in the Cruis''n series.' FROM games WHERE igdb_id = 57379 ON CONFLICT (game_id, language_code) DO NOTHING;
