INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'L.A. Noire', 'L.A. Noire for PlayStation 4 and Xbox One delivers the complete original game and all additional downloadable content with a range of technical enhancements for greater visual fidelity and authenticity, including enhanced lighting and clouds, new cinematic camera angles, high resolution textures and more. L.A. Noire plays natively in 1080p for the PlayStation 4 and Xbox One consoles, and stunning 4K for PlayStation 4 Pro and Xbox One X, capturing the grit and grime of the City of Angels like never before.' FROM games WHERE igdb_id = 59849 ON CONFLICT (game_id, language_code) DO NOTHING;
