INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darkarta: A Broken Heart''s Quest Collector''s Edition', 'Haunted by strange curses from her orphanage days, Mary never knew the story of her dark past until that day. Enter the enchanted ''Netherworld'' where your destiny was written in blood and which whispers of true love. A multi-award winner epic adventure game! Rated by many as their all time favorite!' FROM games WHERE igdb_id = 29344 ON CONFLICT (game_id, language_code) DO NOTHING;
