INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Jackbox Party Pack 4', 'The biggest and fourthiest addition to this storied party game franchise features the blanking fun sequel Fibbage 3 and its new game mode, Fibbage: Enough About You; the web-based frame game Survive the Internet; the spooky date-a-thon Monster Seeking Monster; the deranged debate match Bracketeering; and the one-up art game Civic Doodle. Use your phones or tablets as controllers and play with up to 16 players, plus an audience of up to 10,000!' FROM games WHERE igdb_id = 28213 ON CONFLICT (game_id, language_code) DO NOTHING;
