INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fashioning Little Miss Lonesome', 'When two handsome young men spot the perfect girl to be their first model and help make a name for themselves, they''re determined to go for broke and make her shine—but first they''ll have to get her out of her house! Can these two really give such an anti-social recluse the makeover she needs to be a star? Or will she be the one to change them in this off-beat romantic comedy?' FROM games WHERE igdb_id = 55538 ON CONFLICT (game_id, language_code) DO NOTHING;
