INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Girl on the Train', 'Follow the story of Hana, a high school delinquent who, after a rough day, notices a gorgeous, tall, foreign looking girl on her train ride home. Who is this girl? Why has she never seen her before? Hana hatches a plan to get to know her, but her journey teaches her a lot more than she expected.' FROM games WHERE igdb_id = 74247 ON CONFLICT (game_id, language_code) DO NOTHING;
