INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blue Reflection', 'Blue Reflection, a new RPG title from Gust Studios, puts the player in the shoes of Hinako Shirai, a seemingly normal high school girl who gains the mysterious power of a Reflector, a champion able to manipulate the dimension known as The Common. Follow her story as she creates new bonds and gain new strength as she fights through dangers of The Common.' FROM games WHERE igdb_id = 25708 ON CONFLICT (game_id, language_code) DO NOTHING;
