INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hello Neighbor', 'Hello Neighbor is a stealth horror game about sneaking into your creepy neighbor''s house to figure out what horrible secrets he''s hiding in his basement. You play against an AI that adapts from your actions. Really enjoying climbing through that backyard window? Expect a bear trap there. Sneaking through the front door? There''ll be cameras there soon. Trying to escape? Your neighbor will find a shortcut and catch you.' FROM games WHERE igdb_id = 18167 ON CONFLICT (game_id, language_code) DO NOTHING;
