INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Netflix Infinite Runner', 'Netflix Infinite Runner is a 2D side-scrolling endless runner based on four streaming series of the American entertainment company Netflix. At the start the player selects one of four protagonists: Pablo Escobar (from Narcos), Marco Polo (from Marco Polo), Piper Chapman (from Orange is the New Black) or Mike Wheeler (from Stranger Things). The game uses retro style visuals (8-/16-bit) including chip tune adaptations of the series'' theme songs.' FROM games WHERE igdb_id = 76873 ON CONFLICT (game_id, language_code) DO NOTHING;
