INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uncharted: The Lost Legacy', 'From the critically acclaimed developer, Naughty Dog, comes the first standalone adventure in the Uncharted series. Fan-favorite character, Chloe Frazer, must enlist the aid of renowned mercenary Nadine Ross from Uncharted 4: A Thief’s End in order to recover a fabled ancient Indian artifact and keep it out of the hands of a ruthless war profiteer. Together, they’ll venture deep into the mountains of India in search of the legendary artifact. Along the way, they’ll learn to work together to unearth the mystery of the artifact, fight their way through fierce opposition, and prevent the region from falling into chaos.' FROM games WHERE igdb_id = 26193 ON CONFLICT (game_id, language_code) DO NOTHING;
