INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('brigand-oaxaca', 28045, '2017-07-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8rj0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ars3s.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brigand: Oaxaca', 'Brigand: Oaxaca is a highly difficult post-apocalyptic RPG/FPS set in Mexico. The story will take you from a banana plantation to dark toxic caverns, to the sprawling city of Pochutla, to the flooded coastline, to deadly demon-infested jungles, and more. There are 14 unique skills to upgrade with skill points, ranging from agility to firearms, hacking, hardware, voodoo, and more. Unlock up to 80 special abilities that allow you to do things such as throw your weapon, upgrade your guns, and even control the weather. Dangers include rival tribes fighting for fertile land, mutated ghouls that emerge from their caverns at night, vicious demons that hunger for your flesh, a flooded and irradiated coastline that eats away at civilization, disease, insanity, hunger, and more. You will die often, and you will like it.
