INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dishonored-death-of-the-outsider', 37030, '2017-09-14', 82, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5pd2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3qo1.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dishonored: Death of the Outsider', 'Dishonored: Death of the Outsider is a standalone expansion pack and a sequel to Dishonored 2. The game features all the series hallmarks, including brutal combat systems, unique level design and immersive storytelling that responds to your every choice. With compelling characters and exhilarating action, Death of the Outsider is the perfect entry point for those new to the Dishonored series, while delivering a significant expansion of the gameplay and world for longtime fans.' FROM games WHERE igdb_id = 37030 ON CONFLICT (game_id, language_code) DO NOTHING;
