INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cooking Mama: Sweet Shop', 'In Cooking Mama: Sweet Shop players make and create a wide assortment of delicious looking sweets and puddings, and serve customers in the shop to keep them happy! There are 60 different recipes to create by taking part in over 160 different mini-games. Players use the stylus and even the microphone to cool, slice, stir, bake and decorate their creations. And just like always, don''t worry if you make a mistake - Mama will fix it for you!' FROM games WHERE igdb_id = 27190 ON CONFLICT (game_id, language_code) DO NOTHING;
