INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Getting Over It with Bennett Foddy', 'Getting Over It with Bennett Foddy is a punishing climbing game, a homage to Jazzuo''s 2002 B-Game classic ''Sexy Hiking''. You move the hammer with the mouse, and that''s all there is. With practice, you''ll be able to jump, swing, climb and fly. Great mysteries and a wonderful reward await the master hikers who reach the top of the mountain.
