INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slime Rancher', 'Slime Rancher is a charming, first-person, sandbox experience. Play as Beatrix LeBeau: a plucky, young rancher who sets out for a life a thousand light years away from Earth on the ''Far, Far Range.'' Each day will present new challenges and risky opportunities as you attempt to amass a great fortune in the business of slime ranching. Collect colorful slimes, grow crops, harvest resources, and explore the untamed wilds through the mastery of your all-purpose vacpack.' FROM games WHERE igdb_id = 16287 ON CONFLICT (game_id, language_code) DO NOTHING;
