INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Senko no Ronde 2', 'Senko no Ronde 2 is a reboot of 2010''s Japan-exclusive DUO, a fast-paced one-on-one action game offering a mix of shooting and fighting genres in a mech-filled bullet ballet in space! And with Zuntata alumni, Yasuhisa ''Yack.'' Watanabe on board, you can expect a superb soundtrack too.' FROM games WHERE igdb_id = 29137 ON CONFLICT (game_id, language_code) DO NOTHING;
