INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Late Shift', 'Late Shift is a high stakes FMV crime thriller. After being forced into the robbery of a lucrative auction house, mathematics student Matt is left proving his innocence in the brutal London heist. Your choices will have consequences from the very start, right through to the very end. One small decision could change the entire outcome in a choose-your-own-adventure style gameplay that can lead to one of seven conclusions.' FROM games WHERE igdb_id = 27717 ON CONFLICT (game_id, language_code) DO NOTHING;
