INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Destiny 2', 'Dive into the world of Destiny 2 to explore the mysteries of the solar system and experience responsive first-person shooter combat. Unlock powerful elemental abilities and collect unique gear to customize your Guardian''s look and playstyle. Enjoy Destiny 2’s cinematic story, challenging co-op missions, and a variety of PvP modes alone or with friends. Download for free today and write your legend in the stars.' FROM games WHERE igdb_id = 25657 ON CONFLICT (game_id, language_code) DO NOTHING;
