INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hunting Simulator', 'Hunting Simulator presents 35 species throughout 12 areas, including well-known hunting regions such as the mountains of Colorado, the oak forests of France, and the snowy plains of Alaska. Each environment is populated by superbly modeled animals brought to life with behaviors from a realistic AI. Hunt solo in campaign, free hunt, and shooting practice modes, or join up to two others for online co-op.' FROM games WHERE igdb_id = 27697 ON CONFLICT (game_id, language_code) DO NOTHING;
