INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Torment: Tides of Numenera', 'Torment: Tides of Numenera is a game set in the world of Monte Cook''s new tabletop RPG setting, Numenera. Torment continues the thematic legacy of Planescape: Torment, the critically acclaimed role-playing game from 1999 that''s considered by many to be a hallmark for storytelling in computer RPGs. With Torment, we''re creating a rich role-playing experience that explores similar deep, personal themes.' FROM games WHERE igdb_id = 2004 ON CONFLICT (game_id, language_code) DO NOTHING;
