INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tyler: Model 005', 'Tyler: Model-005 is a 3D action-platformer and exploration game set in the 1950s where you control a spunky miniature robot named Tyler. Many years after being shut down, Tyler is accidentally powered up during the height of a thunderstorm. You set off with Tyler to discover why your creator is missing and what has happened to your home, which is now overrun with robot-sized rats, cockroaches, and more.' FROM games WHERE igdb_id = 29943 ON CONFLICT (game_id, language_code) DO NOTHING;
