INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dirt 4', 'Dirt 4 is all about embracing danger. It’s about the thrill, exhilaration and adrenaline that is absolutely vital to off-road racing. It’s about loving the feeling of pushing flat out next to a sheer cliff drop, going for the gap that’s too small and seeing how much air you can get. Be Fearless.' FROM games WHERE igdb_id = 26948 ON CONFLICT (game_id, language_code) DO NOTHING;
