INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead Ahead: Zombie Warfare', 'Dead Ahead: Zombie Warfare is a zombie-themed strategy game. The main objective is to destroy the enemy barricade while defending the bus by deploying various units and using specific abilities. Summoning units requires courage, a resource accumulated over time, while abilities, along with certain units, demand rage, which is earned by killing enemies. Players can win up to 3 stars at the conclusion of each mission, based on the remaining durability of the bus.' FROM games WHERE igdb_id = 56166 ON CONFLICT (game_id, language_code) DO NOTHING;
