INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Last Day on Earth: Survival', 'Last Day on Earth is a free multiplayer zombie survival strategy game, where all survivors are driven by one target: stay alive and survive as long as you can and shoot walking dead zombies. There is no place left for friendship, love and compassion. A deadly plague pandemic has turned the world into a dead zone. You can trust only yourself in this post apocalyptic world infected with walking dead zombies.' FROM games WHERE igdb_id = 44076 ON CONFLICT (game_id, language_code) DO NOTHING;
