INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'That''s You!', 'The party game all about… you! Set off on a journey of discovery with up to five of your friends and family, and find out what you really think about each other. Joining the fun is easy: all you need is your phone or tablet. Snap a selfie and enjoy tons of funny questions, texting games, and drawing challenges.' FROM games WHERE igdb_id = 37141 ON CONFLICT (game_id, language_code) DO NOTHING;
