INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Long Journey Home', 'The Long Journey Home combines the endless freedom of space with a new open questing system that always leaves you in command. Deliver the stranded Glukkt to his homeworld as he asks, or to your new slaver friends? Attempt to make allies with everyone, or pin your hopes on the tougher races, and hope they never turn on you? Jump by jump, make hard decisions and live with the consequences, in a universe that is never the same twice.' FROM games WHERE igdb_id = 19301 ON CONFLICT (game_id, language_code) DO NOTHING;
