INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snow Moto Racing Freedom', 'Snow Moto Racing Freedom lets you take your rightful place on a high-speed snowmobile on Snocross tracks or through vast beautiful winter landscapes. Experience the thrill of racing so close to your opponents that you can feel the spray of the snow and hear the roar of their engines. Carve your own chosen path through exotic sceneries while stringing together extreme stunts high up in the air to gain that extra speed boost to fly past your opponents.' FROM games WHERE igdb_id = 29593 ON CONFLICT (game_id, language_code) DO NOTHING;
