INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drawn to Death', 'Drawn To Death is a 3rd person, multiplayer only, shooter/brawler that takes place entirely inside the pages of a high school kid''s notebook. All of the game’s levels, characters, and weapons have spawned from the always creative, somewhat twisted imagination of the teenage kid. The game is super violent, over the top, and very fast but it’s also very deep and tactical.' FROM games WHERE igdb_id = 11076 ON CONFLICT (game_id, language_code) DO NOTHING;
