INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reflection of Mine', 'Reflection of Mine is a dark puzzle video game about multiple personality disorder. The entire game takes place in the broken mind of Lilly Witchgan, and the goal is to discover who is real - Lilly herself or one of her many personalities. The plot will tell us about her many minds and how are they fighting each other.' FROM games WHERE igdb_id = 27544 ON CONFLICT (game_id, language_code) DO NOTHING;
