INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Don''t Knock Twice', 'Don''t Knock Twice is a first-person horror game based on a psychologically terrifying urban legend. To save her estranged daughter, a guilt-ridden mother must uncover the frightening truth behind the urban tale of a vengeful, demonic witch. One knock to wake her from her bed, twice to raise her from the dead.
