INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Animal Crossing: Pocket Camp', 'In Animal Crossing: Pocket Camp, it''s up to you to build a fun campsite for you and your friends to enjoy. Tents, hammocks, fireplaces, a stuffed-animal sofa... mix and match to your heart''s content! Make a trendy open-air café, or line up some microphones and guitars to create an outdoor music festival. In the mood for a little extra fun? Set up a merry-go-round and open a theme park. You can even make a pool, or fill the sky with fireworks!' FROM games WHERE igdb_id = 58630 ON CONFLICT (game_id, language_code) DO NOTHING;
