INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blossom-tales-the-sleeping-king', 27994, '2017-03-28', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co232t.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar9rt.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blossom Tales: The Sleeping King', 'Explore a vast open game world in classic action-adventure fashion as Lily, Knight of the Rose! Slash your way through monster-infested dungeons to save the Kingdom of Blossom from eternal darkness. Collect unique weapons, spells, and more during your journey to take down powerful bosses and solve clever puzzles.Be part of a vivid, dynamic story passed down from grandfather to grandchildren by influencing the course of events yourself!' FROM games WHERE igdb_id = 27994 ON CONFLICT (game_id, language_code) DO NOTHING;
