INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yonder: The Cloud Catcher Chronicles', 'Unwind and enjoy the slow life in Yonder: The Cloud Catcher Chronicles, a relaxing open-world adventure game. Yonder is set in the world of Gemea. A natural island paradise with eight distinct environments ranging from tropical beaches to snow-capped summits. Yonder offers a world to lose yourself in; a world filled with the wonder of discovery and the spirit of adventure.' FROM games WHERE igdb_id = 27732 ON CONFLICT (game_id, language_code) DO NOTHING;
