INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Seinarukana -The Spirit of Eternity Sword 2-', 'Thrown into another world, Setoki Nozomu must fight to bring his friends home, while at the same time struggling against the ancient god that sleeps inside him. So begins a journey that will shake the very foundation of the universe. The sequel to the visual novel RPG, Aselia the Eternal.' FROM games WHERE igdb_id = 24971 ON CONFLICT (game_id, language_code) DO NOTHING;
