INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'VTOL VR', 'VTOL VR is a near-futuristic combat flight game built specifically for Virtual Reality. Pilot advanced multi-role jets, using your hands to flip switches, press buttons, and manipulate the virtual flight controls. Take on a wide array of challenges that will put your flight skills, situational awareness, and combat tactics to the test.' FROM games WHERE igdb_id = 47128 ON CONFLICT (game_id, language_code) DO NOTHING;
