INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blackwake', 'Blackwake is a multiplayer team-based shooter centered around naval battles for PC and Mac. Set during the Age of Sail, Blackwake focuses largely on team-based tactics and overall team cooperation. Organizing a ship broadside, assisting your captain in navigating various weather conditions, or just being part of the gun crew - there are many roles to be filled in this shooter.' FROM games WHERE igdb_id = 14206 ON CONFLICT (game_id, language_code) DO NOTHING;
