INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pictopix', 'Pictopix is a puzzle game where you use logic to color squares on grids in order to reveal pictures. Easy to learn and very addictive, the game starts with small grids and ends with much bigger grids. With over 150 colored puzzles, a shuffle mode and a puzzle editor, Pictopix will bring you hours of fun!' FROM games WHERE igdb_id = 26756 ON CONFLICT (game_id, language_code) DO NOTHING;
