INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire Emblem Warriors', '"Clash with legions of soldiers and fierce monsters as Marth, Xander, Corrin, and other Fire Emblem heroes unleashing over-the-top-powerful Dynasty Warriors-style moves. Take direct control of known and original Fire Emblem characters, issue them strategic commands in the midst of battle, pair up heroes to unleash stunning attacks, and more. Unlock new playable heroes, each with their own unique moves, special attacks, weapon types, and voiced dialogue in this large-scale action game from the Hyrule Warriors team."' FROM games WHERE igdb_id = 26769 ON CONFLICT (game_id, language_code) DO NOTHING;
