INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('laytons-mystery-journey-katrielle-and-the-millionaires-conspiracy', 28125, '2017-07-20', 68, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co27zh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1ix0.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Layton''s Mystery Journey: Katrielle and the Millionaire''s Conspiracy', 'Join Katrielle Layton, our new hero, as she becomes embroiled in a casual, quizzical quest, which has its roots in our hero’s search for her missing father, Professor Hershel Layton. You''ll be whisked around London''s famous landmarks, from the Houses of Parliament to Tower Bridge, following Kat, solving case after unlikely case, until she unwittingly uncovers the Millionaires'' Conspiracy.
