INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Semispheres', 'Semispheres is a single-player stealth puzzler where you simultaneously control two characters in connected parallel realities. The game is a mix of mind-bending puzzles and motor coordination challenges. Later levels introduce the co-op aspect of the game where the two sides need to work together (sometimes simultaneously) to progress.' FROM games WHERE igdb_id = 17990 ON CONFLICT (game_id, language_code) DO NOTHING;
