INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Sports Superstars', 'Mario Sports Superstars is a multi‑sport compilation featuring five arcade‑style sports (soccer, baseball, tennis, golf, and horse racing), each with accessible controls and quick matches. Players pick from familiar Mario characters, compete in tournaments or single events, and enjoy local or online multiplayer alongside single‑player challenge modes.' FROM games WHERE igdb_id = 26939 ON CONFLICT (game_id, language_code) DO NOTHING;
