INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Candleman', 'A 3D platformer featuring unique low-light gameplay. Players control the candle and can move, jump and light up. As the candle burns, it reveals safe passage and drips wax but also reduces its height and lifespan. Players must navigate the dark and treacherous landscape and solve puzzles in order to reach the blue light at the end of each level.' FROM games WHERE igdb_id = 27035 ON CONFLICT (game_id, language_code) DO NOTHING;
