INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Drone Racing League Simulator', 'This is what it feels like to fly in the cockpit of the fastest drones! The DRL Simulator will push the limits of your drone racing abilities and prepare you to fly in real life. Explore legendary locations and new worlds. Battle it out with your friends to the finish line. Crash nonstop without wrecking your drone and breaking the bank. Master this game and you can compete for a chance to become a professional pilot in the Drone Racing League!' FROM games WHERE igdb_id = 76735 ON CONFLICT (game_id, language_code) DO NOTHING;
