INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tokyo Dark', 'Tokyo Dark is an anime-style horror adventure game combining point and click and visual novel genres. The story follows Detective Itou across Tokyo, searching for the truth behind her partner''s strange disappearance. Featuring puzzles, stat management, and difficult decisions, Tokyo Dark puts the narrative in the hands of the player. Players'' decisions change their character, opening or locking options and leading to multiple endings.' FROM games WHERE igdb_id = 27531 ON CONFLICT (game_id, language_code) DO NOTHING;
