INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Archaica: The Path Of Light', 'Archaica: The Path Of Light is a visually stunning puzzle game with lasers and mirrors, that enraptures gamers not only with finely designed levels, but also with an interesting storyline. In this game we become the Chosen One from the nation that believes walking the legendary Path of Light will save the world from impending disaster. We revive ancient mechanisms, explore secrets of an ancient civilization, and discover the true destiny of The Path along the way through extraordinary realms.' FROM games WHERE igdb_id = 25625 ON CONFLICT (game_id, language_code) DO NOTHING;
