INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'This Grand Life', 'In This Grand Life, you create a character, manage their finances and help them achieve their goals. Cruise your way through life with a silver spoon, or struggle endlessly to find employment as a convicted felon. You cannot control your past, but you can change your future. What choices will you make?' FROM games WHERE igdb_id = 59250 ON CONFLICT (game_id, language_code) DO NOTHING;
