INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rocket Wars', 'Rocket Wars is a fast-paced local multiplayer game for up to 4 players! The game features crazy weapons, lots of powerups and several game modes. Rocket Wars is the go-to party game when you have people over and are looking for fast and furious pvp battles! In Rocket Wars you take control of a spaceship with different strengths and weaknesses and proceed to do all in your power to kill your enemies.' FROM games WHERE igdb_id = 36630 ON CONFLICT (game_id, language_code) DO NOTHING;
