INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aliens Go Home Run!', 'Aliens Go Home Run is a brick-breaking alien-busting action game that puts you in the shoes of Sally, a young girl with a passion for baseball. When she hits a home run so hard that it flies into space, it crashes on a faraway planet and creates a crater in the process. Now, the aliens from that planet are invading Earth, and its up to Sally to save the day! Unlike most breakout games, the game isn''t over if the ball touches the ground. Instead, the player has to avoid various projectiles shot by enemies. If they get hit, they get a strike, and three strikes means they''re out! With plenty of power-ups, 70 exciting levels, 8 bosses, and a full-blown level editor, Aliens Go Home Run is breakout like you''ve never seen it before.' FROM games WHERE igdb_id = 26835 ON CONFLICT (game_id, language_code) DO NOTHING;
