INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Gummy''s Life', 'A Gummy’s Life is a local & online party multiplayer with candy-coated physics-based fights. Choose your favorite gummy, customize it to your taste and show who rules over the sugar! Play with friends, family or AIs in multiple manic game modes or battle online - as easy as taking candy from a baby.' FROM games WHERE igdb_id = 29662 ON CONFLICT (game_id, language_code) DO NOTHING;
