INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World to the West', 'World to the West is a pulpy, cartoony top down action adventure inspired by European adventure comics. Take control of four unique characters —Lumina the Teslamancer, Knaus the orphan, Miss Teri the mind bender and the gloriously mustachioed strongman, Lord Clonington—, each with their their own motivations, skills and interweaving storylines, as they seek to escape the dark shadow of an ancient prophecy. Travel trough corrupt colonies, lush jungles and frozen tundras, as you snoop through the secrets of a forgotten civilization.' FROM games WHERE igdb_id = 27518 ON CONFLICT (game_id, language_code) DO NOTHING;
