INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Man O'' War: Corsair - Warhammer Naval Battles', 'Man O'' War: Corsair is a video game of high adventure, naval combat and exploration based on the Games Workshop classic Man O'' War table top game. Play as a rogue Captain of the Empire or Champion of Chaos, personally navigating your vessel in third person across the Great Western Ocean while plundering enemy ships, visiting ports, trading and making legends of your deeds across the land and sea! Engage in boarding actions, with direct control over your Captain and take the fight to the enemy.' FROM games WHERE igdb_id = 25058 ON CONFLICT (game_id, language_code) DO NOTHING;
