INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Witch''s Isle', 'The Witch''s Isle is an adventure game that takes place in a dream-like town on a solitary island. One night, one of the villagers gets a sudden visit from a witch, who puts her under a curse: if she doesn''t find the witch''s stolen urn by 4:00 a.m., the curse will kill her. She begins her search, but along the way she starts hearing more and more about the secret of the witch.' FROM games WHERE igdb_id = 55764 ON CONFLICT (game_id, language_code) DO NOTHING;
