INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blockhood', 18339, '2017-05-10', 75, 'https://images.igdb.com/igdb/image/upload/t_cover_big/vlgd8s9sdltepdelpg5h.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4vri.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Block''hood', 'Block’hood is a neighborhood-building simulator that celebrates the diversity and experimentation of cities and the unique ecosystems within them. Budding city planners will have access to 90+ building blocks to arrange and combine and to create unique neighborhoods and discover the implications of their designs. The game will embark on a story of ecology and understanding as additional resources are always needed to unlock new blocks, configurations, and combinations to create more prosperous neighborhoods. Throughout the design process, players will need to avoid the decay of their city blocks by making sure each unit doesn’t run out of resources and become a strain on the complimentary units around them.
