INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'River City Ransom: Underground', 'Many years after vanquishing Slick on the school rooftop, Alex and Ryan must take to the streets again. Help a new crop of fighters defeat the hordes of River City, and clear their name in a sinister kidnapping plot. You''ll earn money, unlock moves, and upgrade your skills in a sprawling city on the brink of total chaos. This modern take on an old classic features over 500 unique street fighting moves, dozens of weapons, secrets galore, and a bonus arena fighting mode.' FROM games WHERE igdb_id = 27038 ON CONFLICT (game_id, language_code) DO NOTHING;
