INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lone Echo', 'In Lone Echo’s single player story, you’ll be transported to an advanced mining facility within the rings of Saturn, complete with a detailed space station, expansive outer-space environments, and interactive space equipment. Taking on the role of Jack—an advanced artificial intelligence with a state-of-the-art synthetic body—you’ll help Captain Olivia Rhodes solve an increasingly threatening mystery as you use futuristic tools, clever problem solving, and interactive dialogue to engage with the world around you.' FROM games WHERE igdb_id = 24917 ON CONFLICT (game_id, language_code) DO NOTHING;
