INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Randall', 'In a dystopian world that doesn''t seem like such a departure from our own future, people are content living under constant surveillance and absolute control. Players take on the part of Randall, a powerful telepath with a touch of schizophrenia. His abilities allow him to control and play as every single character on screen, seamlessly swapping between them, exploiting every power that they have.' FROM games WHERE igdb_id = 34659 ON CONFLICT (game_id, language_code) DO NOTHING;
