INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Big Journey', 'The Big Journey is a casual, low-difficulty, cat-themed adventure game with motion controls created by a small Ukranian studio called Catfishbox. Players tilt their devices (or use optional on-screen buttons) to roll and bounce Mr. Whiskers through a beautiful storybook-like world as he searches for his missing friend, and enjoys a toe-tapping original soundtrack from an indie folk band. The game is available for iOS and Android.' FROM games WHERE igdb_id = 69549 ON CONFLICT (game_id, language_code) DO NOTHING;
