INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hangry Bunnies From Mars', 'How long will you survive against an unrelenting horde of fluffy-wuffy alien bunnies? Join up with the Critter Death Squad as the team''s chief exterminator (who may or may not be a clone) and arm yourself to the teeth with epic weaponry designed by the team’s unhinged mad scientist, get tactical updates from a KGB pizza delivery driver, and fight to keep Earth off the dinner menu!' FROM games WHERE igdb_id = 54698 ON CONFLICT (game_id, language_code) DO NOTHING;
