INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Only One Hope', 'Only One Hope - is a game in the genre of survival horror, where the main character gets into a shipwreck. Regaining consciousness he was on the island. His only hope is to learn how to survive and return to his home! Forget everything about your simple past life! Now you will have to overcome a lot of different problems: hunger, thirst, cold and darkness...' FROM games WHERE igdb_id = 29727 ON CONFLICT (game_id, language_code) DO NOTHING;
