INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tricolour Lovestory', 'Time flies and never comes back. But with an incredible 1-million-word script and 100+ original CGs, this game will take you back to when you were young, simple and pure. Go and get the love of your life back, start something new, or end everything in flame, that''s for you to decide!' FROM games WHERE igdb_id = 55803 ON CONFLICT (game_id, language_code) DO NOTHING;
