INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Road Fist', 'Road Fist is a Beat ''em up style action game inspired by classic 80''s / 90''s fighting movies. The 3D movement provides a new panorama within the bilateral view (2D), adding more freedom and requiring a greater sense of direction from the player. The gameplay and difficulty is based on games like Dark Souls, where a stamina system is implemented and each enemy encountered can be deadly. The gloomy look comes accompanied by a stimulating, dense and varied soundtrack.' FROM games WHERE igdb_id = 26199 ON CONFLICT (game_id, language_code) DO NOTHING;
