INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bombergirl', 'Based on the block-destroying gameplay of Bomberman, Bombergirl tasks players with destroying the opposing team’s base before the other team in four-versus-four cooperative battles. By adding new game properties such as this, it is not only fun to play, it is also fun to watch. And with the button that pops out at the end, a match of Bombergirl is a sight worth seeing.' FROM games WHERE igdb_id = 27285 ON CONFLICT (game_id, language_code) DO NOTHING;
