INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Occultic;Nine', 'Occultic;Nine is an Japanese visual novel that is based on a light novel of the same name. The game is descibed as a "Paranormal Science Novel". The story follows nine idiosyncratic individuals. Little incongruities that occur around these nine eventually lead to a larger, unimaginable event that may alter what is considered common sense in this world. Despite being by the same makers and sharing a similar naming scheme, Occultic;Nine is not a part of 5pb''s Science Adventure series of adventure games.' FROM games WHERE igdb_id = 11774 ON CONFLICT (game_id, language_code) DO NOTHING;
