INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arktika.1', 'From the creators of Metro 2033, Metro: Last Light, and Metro Redux comes a new vision of the apocalypse. ARKTIKA.1 is a highly immersive, action-packed, first-person shooter designed exclusively for Oculus Touch. Nearly a century in the future, the world has fallen into a new ice age in the aftermath of a silent apocalypse. Only the equatorial regions are still habitable, yet pockets of humanity survive in small numbers all over the planet, hanging onto existence in the resource-rich territories to the north and south--resources that everyone wants to control... Protect the colony in the wastelands of old Russia from raiders, marauders, and strange creatures. Be the savior. Give humanity a second chance.' FROM games WHERE igdb_id = 24833 ON CONFLICT (game_id, language_code) DO NOTHING;
