INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Park Bound', 'Park Bound is a massively multiplayer playground featuring player crafted parks. Each park contains a variety of worlds to explore, play, and meet other players. Every world presents goals and challenges to overcome with unique collectible treasures that can unlock special worlds in the park. Players can pick up jetpacks, soar the sky with hang-gliders, and even roll inside balls to complete objectives.' FROM games WHERE igdb_id = 40524 ON CONFLICT (game_id, language_code) DO NOTHING;
