INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boom Ball 3 for Kinect', 'It''s boom time again! Boom Ball 3 upgrades the classic Kinect ping-pong game with 50 scenic levels featuring a festival of cute cubic critters. Also includes improved 2-player mode and 3 new difficulty options for novices and veterans alike. Customize your paddles with pictures or take your own photos with Kinect. Suitable for all ages, shapes and sizes!' FROM games WHERE igdb_id = 83757 ON CONFLICT (game_id, language_code) DO NOTHING;
