INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 12206 AND rs.code = 'PEGI' AND r.code = '18' ON CONFLICT DO NOTHING;
